def compute(vars):
    values = [vars["v1"], vars["v2"]]
    average_value = sum(values) / len(values)
    return {
        "value": average_value,
        "trace": {
            "values": values,
            "count": len(values),
            "average": average_value,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": None
            }
        }
    }
